#[path="../owner_registry.rs"]mod owner_registry;#[path="../owner_budget.rs"]mod owner_budget;#[path="../journal.rs"]mod journal;#[path="../owner.rs"]mod owner;
use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicUsize,Ordering};use ingetrazo_core::mesh::Mesh;use glam::DVec3;
static FAIL:AtomicUsize=AtomicUsize::new(0);struct Fault;unsafe impl GlobalAlloc for Fault{unsafe fn alloc(&self,l:Layout)->*mut u8{if FAIL.fetch_update(Ordering::SeqCst,Ordering::SeqCst,|n|if n>0{Some(n-1)}else{None}).ok()==Some(1){std::ptr::null_mut()}else{System.alloc(l)}}unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l)}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{if FAIL.fetch_update(Ordering::SeqCst,Ordering::SeqCst,|n|if n>0{Some(n-1)}else{None}).ok()==Some(1){std::ptr::null_mut()}else{System.realloc(p,l,n)}}}#[global_allocator]static ALLOC:Fault=Fault;
fn main(){let mut refused=0;for failure in 1..=12{let mut m=Mesh::new();for p in [DVec3::ZERO,DVec3::X,DVec3::Y,DVec3::Z]{m.add_vertex(p);}m.add_face(vec![0,1,2],vec![]).unwrap();m.add_face(vec![1,0,3],vec![]).unwrap();let budget=owner_budget::OwnerBudget::new(None);let mut o=owner::JournalOwner::new_with_budget(m,budget.clone()).unwrap();let before=o.mesh().clone();let charge=budget.snapshot().total();let positions=vec![DVec3::Z,DVec3::Y,DVec3::X,DVec3::ZERO];let loops=vec![(vec![2,3,0],vec![]),(vec![3,2,1],vec![])];FAIL.store(failure,Ordering::SeqCst);let result=o.prepare_graph_order_as(&[3,2,1,0],&[4,3,2,1,0],&[1,0],positions,loops,uuid::Uuid::new_v4());assert!(result.is_err());drop(result);assert_eq!(FAIL.load(Ordering::SeqCst),0);assert_eq!(o.mesh(),&before);assert_eq!(o.history_counts(),(0,0));assert_eq!(budget.snapshot().total(),charge);refused+=1;}println!("{}",serde_json::json!({"actual_native_allocation_refusals":refused,"graph_history_and_charges_preserved":true,"bigint_and_vm_heap_failure_included":false,"production_enabled":false}));}
